// <auto-generated/>
using CalculadoraFilamentoPro.App.Interfaces.Authentication;
using CalculadoraFilamentoPro.Components.Shared.Notifications;
using Microsoft.AspNetCore.Components;

namespace CalculadoraFilamentoPro.Components.Pages
{
    public partial class Login
    {
        [Inject]
        private IAuthenticationService AuthenticationService { get; set; } = default!;

        [Inject]
        private NavigationManager Navigation { get; set; } = default!;

        private string UserName = string.Empty;

        private string Senha = string.Empty;

        private bool MostrarSenha;

        private bool LembrarUsuario;

        private bool Carregando;

        private ToastNotification? Toast;

        private async Task SignIn()
        {

            try
            {
                var result = await AuthenticationService.LoginAsync(UserName, Senha);

                if (!result.Success) throw new Exception(result.Error);

                _ = Toast!.ShowSuccess("Login realizado com sucesso.");

                await Task.Delay(700);

                Navigation.NavigateTo("/home");
            }
            catch (Exception ex)
            {
                _ = Toast!.ShowError(ex.Message);
            }
        }

        private void ShowPassword()
            => MostrarSenha = !MostrarSenha;

        private void SignUp()
            => Navigation.NavigateTo("/register");
    }
}